exercises.solution:
export function blockedPermille(blockingCallsPerSec, blockMs) {
  return blockingCallsPerSec * blockMs;
}

export function worstStallMs(blockMs, chunks) {
  return blockMs / chunks;
}

export function chunksForStall(blockMs, maxStallMs) {
  return Math.ceil(blockMs / maxStallMs);
}

