exercises.solution:
export function hashesPerSec(threadpoolSize, cores, hashMs) {
  return (Math.min(threadpoolSize, cores) * 1000) / hashMs;
}

export function burstFinishMs(burst, threadpoolSize, hashMs) {
  return Math.ceil(burst / threadpoolSize) * hashMs;
}

export function queuedJobStartMs(jobsAhead, threadpoolSize, hashMs) {
  return Math.floor(jobsAhead / threadpoolSize) * hashMs;
}

