exercises.solution:
export function firstUnsafeHop(pairs) {
  return pairs.findIndex(([callerIdleMs, calleeIdleMs]) => calleeIdleMs <= callerIdleMs);
}

export function raiseCalleeTimeouts(pairs, marginMs) {
  return pairs.map(([callerIdleMs, calleeIdleMs]) => Math.max(calleeIdleMs, callerIdleMs + marginMs));
}

