exercises.solution:
export function refusedPerPod(podQps, endpointLagSec, preStopSleepSec) {
  return podQps * Math.max(0, endpointLagSec - preStopSleepSec);
}

export function maxPreStopSleepSec(graceSec, longestRequestSec) {
  return Math.max(0, graceSec - longestRequestSec);
}

export function drainIsSafe(graceSec, preStopSleepSec, longestRequestSec, endpointLagSec) {
  return preStopSleepSec >= endpointLagSec && preStopSleepSec + longestRequestSec <= graceSec;
}
